<?php
require_once __DIR__ . '/../include/session.php';require_once __DIR__ . '/../include/config.php';
if(empty($_SESSION['user'])){header('Location: '.BASE_URL.'/index.php');exit;}if(($_SESSION['user']['role']??'')!=='Admin'){http_response_code(403);exit('Hanya Admin yang dapat mengubah status surat.');}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: '.BASE_URL.'/admin/status_surat/index.php');exit;}
$token=$_POST['csrf_token']??'';if(!is_string($token)||empty($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)){http_response_code(419);exit('Formulir kedaluwarsa. Silakan kembali dan coba lagi.');}
$id=max(0,(int)($_POST['id']??0));$newStatus=trim((string)($_POST['status_baru']??''));$note=trim((string)($_POST['catatan']??''));if(strlen($note)>500)$note=substr($note,0,500);$userId=(int)$_SESSION['user']['id'];
$stmt=$conn->prepare('SELECT id,jenis_surat,status,tanggal_surat FROM surat WHERE id=? LIMIT 1');$stmt->bind_param('i',$id);$stmt->execute();$letter=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$letter){$_SESSION['flash']=['type'=>'error','message'=>'Surat tidak ditemukan.'];header('Location: '.BASE_URL.'/admin/status_surat/index.php');exit;}
$allowed=$letter['jenis_surat']==='Masuk'?['Diterima','Menunggu Disposisi','Dalam Proses','Selesai','Ditolak']:['Draft','Dalam Proses','Selesai','Dibatalkan'];if(!in_array($newStatus,$allowed,true)){$_SESSION['flash']=['type'=>'error','message'=>'Status yang dipilih tidak valid.'];header('Location: '.BASE_URL.'/admin/status_surat/detail.php?id='.$id);exit;}if($newStatus===$letter['status']){$_SESSION['flash']=['type'=>'info','message'=>'Status surat tidak berubah.'];header('Location: '.BASE_URL.'/admin/status_surat/detail.php?id='.$id);exit;}
$oldStatus=$letter['status'];if($note==='')$note='Status surat diperbarui menjadi '.$newStatus.'.';
try{$conn->begin_transaction();$update=$conn->prepare('UPDATE surat SET status=?,updated_by=? WHERE id=?');$update->bind_param('sii',$newStatus,$userId,$id);$update->execute();$update->close();$log=$conn->prepare('INSERT INTO surat_status_logs (surat_id,status_lama,status_baru,catatan,changed_by) VALUES (?,?,?,?,?)');$log->bind_param('isssi',$id,$oldStatus,$newStatus,$note,$userId);$log->execute();$log->close();if($newStatus==='Selesai'){$year=(int)date('Y');$location=$letter['jenis_surat']==='Masuk'?'Arsip Digital / Surat Masuk':'Arsip Digital / Surat Keluar';$archive=$conn->prepare('INSERT INTO arsip_surat (surat_id,tahun_arsip,lokasi_arsip,keterangan,archived_by,archived_at) VALUES (?,?,?,?,?,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE tahun_arsip=VALUES(tahun_arsip),lokasi_arsip=VALUES(lokasi_arsip),keterangan=VALUES(keterangan),archived_by=VALUES(archived_by),archived_at=CURRENT_TIMESTAMP');$archive->bind_param('iissi',$id,$year,$location,$note,$userId);$archive->execute();$archive->close();}else{$deleteArchive=$conn->prepare('DELETE FROM arsip_surat WHERE surat_id=?');$deleteArchive->bind_param('i',$id);$deleteArchive->execute();$deleteArchive->close();}$conn->commit();$_SESSION['flash']=['type'=>'success','message'=>'Status surat berhasil diperbarui.'];}catch(Throwable $error){$conn->rollback();$_SESSION['flash']=['type'=>'error','message'=>'Status gagal diperbarui. Periksa kembali database.'];}header('Location: '.BASE_URL.'/admin/status_surat/detail.php?id='.$id);exit;
